/* Volta Studio — Design System */

/* === TOKENS === */
:root {
  /* Colors - OKLCH for perceptual uniformity */
  --bg-primary: oklch(96% 0.015 85);       /* Warm cream */
  --bg-secondary: oklch(94% 0.02 80);      /* Slightly darker cream */
  --text-primary: oklch(15% 0.02 265);     /* Near-black */
  --text-secondary: oklch(50% 0.02 265);   /* Mid gray */
  --accent-warm: oklch(65% 0.15 50);       /* Terracotta */
  --accent-sage: oklch(60% 0.10 140);      /* Sage green */
  --accent-sand: oklch(75% 0.08 70);       /* Sand */

  /* Typography */
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', -apple-system, sans-serif;

  /* Spacing scale (8px base) */
  --space-xs: 0.5rem;    /* 8px */
  --space-sm: 1rem;      /* 16px */
  --space-md: 1.5rem;    /* 24px */
  --space-lg: 2rem;      /* 32px */
  --space-xl: 3rem;      /* 48px */
  --space-2xl: 4rem;     /* 64px */
  --space-3xl: 6rem;     /* 96px */
  --space-4xl: 8rem;     /* 128px */

  /* Layout */
  --max-width: 1400px;
  --content-width: 800px;
  --gutter: var(--space-lg);
}

/* === RESET === */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* === TYPOGRAPHY === */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 {
  font-size: clamp(2.5rem, 8vw, 5rem);
}

h2 {
  font-size: clamp(2rem, 5vw, 3.5rem);
}

h3 {
  font-size: clamp(1.5rem, 3vw, 2rem);
}

p {
  max-width: 65ch;
}

.text-serif {
  font-family: var(--font-serif);
}

.text-large {
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  line-height: 1.4;
}

.text-small {
  font-size: 0.875rem;
  letter-spacing: 0.02em;
}

.text-uppercase {
  text-transform: uppercase;
  letter-spacing: 0.15em;
  font-size: 0.75rem;
}

/* === LAYOUT === */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.container--narrow {
  max-width: var(--content-width);
}

.section {
  padding: var(--space-3xl) 0;
}

/* === NAVIGATION === */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-md) var(--gutter);
  display: flex;
  justify-content: space-between;
  align-items: center;
  mix-blend-mode: difference;
}

.nav__logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
}

.nav__links {
  display: flex;
  gap: var(--space-lg);
}

.nav__link {
  font-size: 0.875rem;
  color: #fff;
  letter-spacing: 0.02em;
  transition: opacity 0.2s ease;
}

.nav__link:hover {
  opacity: 0.6;
}

/* Hamburger Menu */
.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 6px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 110;
}

.nav__hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.nav__hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 6px);
}

.nav__hamburger.active span:nth-child(2) {
  opacity: 0;
}

.nav__hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -6px);
}

/* Mobile Menu Overlay */
.nav__overlay {
  position: fixed;
  inset: 0;
  background: var(--text-primary);
  z-index: 105;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.nav__overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.nav__overlay-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-md);
}

.nav__overlay-link {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 8vw, 4rem);
  color: #fff;
  letter-spacing: -0.02em;
  transition: opacity 0.2s ease;
}

.nav__overlay-link:hover {
  opacity: 0.6;
}

/* === MARQUEE === */
.marquee {
  overflow: hidden;
  padding: var(--space-md) 0;
  border-top: 1px solid oklch(85% 0.01 85);
  border-bottom: 1px solid oklch(85% 0.01 85);
}

.marquee__track {
  display: flex;
  gap: var(--space-xl);
  animation: marquee 20s linear infinite;
}

.marquee__track--reverse {
  animation-direction: reverse;
}

.marquee__item {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 500;
  white-space: nowrap;
  color: var(--text-secondary);
}

.marquee__item::after {
  content: " ◦";
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* === MEDIA SHOWCASE === */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-sm);
  padding: var(--space-sm);
}

.media-showcase__item {
  aspect-ratio: 4 / 3;
  background: var(--accent-sand);
}

.media-showcase__item:nth-child(2) {
  background: var(--accent-warm);
}

.media-showcase__item:nth-child(3) {
  background: var(--accent-sage);
}

/* === BUTTONS === */
.btn {
  display: inline-block;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.875rem;
  letter-spacing: 0.02em;
  border: 1px solid currentColor;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.btn:hover {
  background: var(--text-primary);
  color: var(--bg-primary);
}

/* === DIVIDER === */
.divider {
  width: 100%;
  height: 1px;
  background: oklch(85% 0.01 85);
  margin: var(--space-3xl) 0;
}

/* === RESPONSIVE === */
@media (max-width: 768px) {
  :root {
    --gutter: var(--space-md);
    --space-3xl: 4rem;
    --space-4xl: 5rem;
  }

  .nav__links {
    display: none;
  }

  .nav__hamburger {
    display: flex;
  }

  .media-showcase {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: clamp(2rem, 10vw, 3rem);
  }
}

